const idealRange = context.season === 'winter' ? '35–50 %' : context.season === 'summer' ? '40–60 %' : '40–55 %';
function humidityAdvice() {
  if (humidityStatus === 'too_dry') {
    const outdoorAdvice = dryingBenefit !== null && dryingBenefit > 5 ? "L’air extérieur assécherait encore la pièce une fois réchauffé. " : '';
    return `${outdoorAdvice}Garde l’aération quotidienne et la ventilation habituelle, évite de surchauffer et surveille le taux avant d’humidifier davantage.`;
  }
  const storm = String(data.condition_meteo_main).toLowerCase() === 'thunderstorm';
  if (storm || (wind !== null && wind >= 12)) return "Orage ou vent fort : privilégie la VMC ou l’extraction ; aère brièvement quand les conditions le permettent.";
  if (nativeWindow === true && effectiveVentilation) return "Tado signale déjà une ouverture. L’air extérieur peut assécher la pièce ; surveille la baisse d’humidité et évite de prolonger inutilement l’aération.";
  if (effectiveVentilation) {
    const duration = outdoor <= 8 || (wind !== null && wind >= 5) ? '5 à 10' : 'environ 10';
    const rain = ['rain', 'drizzle', 'snow'].includes(String(data.condition_meteo_main).toLowerCase()) ? " Choisis une ouverture abritée des précipitations." : '';
    return `Aérer ${duration} minutes peut assécher la pièce : l’air extérieur ramené à ${rounded(indoor, 1)} °C serait à environ ${rounded(equivalentOutsideRh, 0)} % HR.${rain} Garde la ventilation habituelle.`;
  }
  if (dryingBenefit === null) return "Données extérieures insuffisantes pour conseiller une aération déshumidifiante. Garde la ventilation habituelle et vérifie les sources d’humidité.";
  return "L’air extérieur n’est pas assez sec pour déshumidifier efficacement par une longue aération. Garde la ventilation habituelle, utilise l’extraction et vérifie les sources d’humidité ; un déshumidificateur peut aider si cela persiste.";
}
const alertMessage = abnormal ? [
  humidityStatus === 'too_dry' ? `🌵 Air ${humiditySeverity === 'critical' ? 'très ' : ''}sec : ${rounded(humidity, 1)} % HR.` : `💧 ${condensationRisk && humidity < high ? 'Risque de condensation sur paroi froide' : humiditySeverity === 'critical' ? 'Air très humide' : 'Air humide'} : ${rounded(humidity, 1)} % HR.`,
  insideOk ? `Intérieur : ${rounded(indoor, 1)} °C. Repère de confort saisonnier : ${idealRange}.` : `Repère de confort saisonnier : ${idealRange}.`,
  condensationRisk ? `Point de rosée : ${rounded(dewInside, 1)} °C ; paroi ${measuredSurface === null ? 'estimée' : 'mesurée'} à ${rounded(surfaceTemperature, 1)} °C. ${measuredSurface === null ? 'Estimation à vérifier sur place.' : ''}` : '',
  humidityAdvice()
].filter(Boolean).join('\n') : null;

// Only successful Telegram acknowledgements update lastSent; failed messages remain retryable.
const windowReminder = setting('WINDOW_REMINDER_MINUTES', 60, 15, 360) * MINUTE;
const sendWindowAlert = data.tado_api_ok === true && nativeWindow === true && (window.lastSent?.episodeId !== window.episodeId || now - window.lastSent.ts >= windowReminder);
const windowMessage = sendWindowAlert ? [
  window.lastSent?.episodeId === window.episodeId ? '🪟 Tado signale toujours une fenêtre ouverte.' : '🪟 Tado vient de signaler une fenêtre ouverte.',
  insideOk ? `Intérieur : ${rounded(indoor, 1)} °C${humidityOk ? ` · Humidité : ${rounded(humidity, 1)} %` : ''}.` : 'Température intérieure indisponible.',
  action === 'UPDATE' ? `Consigne demandée : ${target} °C, mode ON.` : insideOk && current === eco && power === 'ON' ? `Consigne actuelle : ${eco} °C, mode ON.` : 'Vérifie le chauffage dans Tado : aucune nouvelle consigne n’a été envoyée par cette décision.',
  'Vérifie la fenêtre. Tado déduit l’ouverture des variations de température/humidité ; ce signal ne remplace pas un capteur de contact.'
].join('\n') : null;

return [{ json: {
  ...data,
  cible: target,
  target_mode: targetMode,
  action,
  reason,
  delayOk,
  targetChangedEnough,
  sendHumAlert,
  alertMessage,
  sendWindowAlert,
  windowMessage,
  humidity_alert_meta: sendHumAlert ? { ts: now, family: humidityStatus, severity: humiditySeverity, episodeId: hum.activeEpisode.id } : null,
  window_alert_meta: sendWindowAlert ? { ts: now, episodeId: window.episodeId } : null,
  debug_thermique: {
    timezone, ...context, presence, presence_source: typeof data.presence === 'boolean' ? 'tado' : 'configuration',
    confort_base: rounded(baseComfort), correction_meteo: rounded(weatherCorrection), confort_cible: rounded(comfort),
    consigne_avant_arrondi: rounded(requested), tendance_deg_par_heure: rounded(trend), echantillons_tendance: trendPoints.length,
    anticipation_horaire: preheating, fenetre_active: windowActive, surchauffe: !!state.overheat, temps_doux: !!state.warmStandby
  },
  debug_solaire: {
    elevation: rounded(solar?.elevation), azimut: rounded(solar?.azimuth), nuages: clouds,
    gain_estime: rounded(solarScore), reduction_solaire_c: rounded(solarReduction), reduction_tendance_c: rounded(trendReduction)
  },
  debug_humidite: {
    statut: humidityStatus, severite: humiditySeverity, plage_ideale: idealRange,
    seuil_bas: low, seuil_haut: high, seuil_critique_bas: criticalLow, seuil_critique_haut: criticalHigh,
    point_rosee_interieur_c: rounded(dewInside), point_rosee_exterieur_c: rounded(dewOutside),
    humidite_absolue_interieure_g_m3: pressureInside === null ? null : rounded(216.7 * pressureInside / (indoor + 273.15)),
    humidite_absolue_exterieure_g_m3: pressureOutside === null ? null : rounded(216.7 * pressureOutside / (outdoor + 273.15)),
    humidite_exterieure_ramenee_interieur_percent: rounded(equivalentOutsideRh), gain_aeration_points_hr: rounded(dryingBenefit),
    aeration_deshumidifiante: effectiveVentilation, temperature_paroi_c: rounded(surfaceTemperature),
    paroi_estimee: measuredSurface === null, marge_condensation_c: rounded(condensationMargin), risque_condensation: condensationRisk,
    nombre_mesures_consecutives: hum.count ?? 0, confirme: confirmed, meteo: data.condition_meteo
  }
} }];

